def compute(vars):
    balances = [vars["v1"], vars["v2"]]
    years_exceeding_threshold = sum(1 for balance in balances if balance > 1)
    return {
        "value": years_exceeding_threshold,
        "trace": {
            "balances": balances,
            "threshold": 1,
            "years_exceeding_threshold": years_exceeding_threshold,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
